  try{if(profileCommittedChecksum&&profileIntegrityChecksum(profile)===profileCommittedChecksum)return true}catch(_e){}
  if(!acquireProfileWriteLease()){restoreCommittedProfileInMemory(false);return false;}
  let saved=false;
  try{
    profile=stampProfileForSave(profile);
    const result=writeCurrentProfile(profile,{preservePrevious:true});
    profile=result.profile;rememberCommittedProfile(profile);clearProfileSaveFailure();
    saved=true;
  }catch(e){
    restoreCommittedProfileInMemory(false);noteProfileSaveFailure(e);
    if(e?.code==='PROFILE_REVISION_CONFLICT')markProfileConflict();
    else{profileWriteBlocked=true;console.warn('silent save failed',e);setTimeout(()=>refreshPwaHealth?.(),0);}
    return false;
  }finally{releaseProfileWriteLease()}
  try{queueRecoveryCheckpoint('autosave',false)}catch(e){console.warn('Recovery checkpoint queue failed',e)}
  return saved;
}

